    families: &'a [prometheus::proto::MetricFamily],
    name: &str,
    labels: &[(&str, &str)],
) -> &'a prometheus::proto::Metric {
    let family = families
        .iter()
        .find(|family| family.name() == name)
        .unwrap_or_else(|| panic!("missing metric family {name}"));
    family
        .get_metric()
        .iter()
