            r#"{"nonsense":"boom"}"#,
            r#"{"error":"a","stop":"b"}"#,
            "{}",
            "17",
        ] {
            assert!(
                serde_json::from_str::<FinishReason>(json).is_err(),
                "{json} should not deserialize"
            );
        }
    }

